export const formatValue = (value, datasetIndex, unit) => {
    if (unit) {
        if (typeof unit === "function") {
            return unit(datasetIndex, value);
        }
        const unitValue = typeof unit === "string" ? unit : unit[datasetIndex];
        if (unitValue === "%") {
            return value + unitValue;
        }
        // eslint-disable-next-line @typescript-eslint/restrict-template-expressions
        return `${value} ${unitValue || ""}`;
    }
    return value;
};
